'use strict';

/**
* Return the index of the first element in a double-precision floating-point strided array which is greater than a corresponding element in another double-precision floating-point strided array.
*
* @module @stdlib/blas-ext-base-dfirst-index-greater-than
*
* @example
* import Float64Array from '@stdlib/array-float64';
* import dfirstIndexGreaterThan from '@stdlib/blas-ext-base-dfirst-index-greater-than';
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( [ 2.0, 2.0, 2.0, 2.0 ] );
*
* var idx = dfirstIndexGreaterThan( 4, x, 1, y, 1 );
* // returns 2
*
* @example
* import Float64Array from '@stdlib/array-float64';
* import dfirstIndexGreaterThan from '@stdlib/blas-ext-base-dfirst-index-greater-than';
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( [ 2.0, 2.0, 2.0, 2.0 ] );
*
* var idx = dfirstIndexGreaterThan.ndarray( 4, x, 1, 0, y, 1, 0 );
* // returns 2
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var dfirstIndexGreaterThan;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dfirstIndexGreaterThan = main;
} else {
	dfirstIndexGreaterThan = tmp;
}


// EXPORTS //

export default dfirstIndexGreaterThan;

// exports: { "ndarray": "dfirstIndexGreaterThan.ndarray" }
